+import { useEffect, useState } from 'react';
+
+export function Boundary({ serverComponent, clientComponent }) {
+  const [isClient, setIsClient] = useState(false);
+
+  useEffect(() => {
+    setIsClient(true);
+  }, []);
+
+  if (!isClient) {
+    return <div>{serverComponent}</div>;
+  }
+
+  return <div>{clientComponent}</div>;
+}
